<?php require_once __DIR__.'/includes/bootstrap.php';require_role('customer');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=db()->prepare('SELECT t.*,b.business_name,b.location,s.service_name FROM queue_tickets t JOIN businesses b ON b.id=t.business_id JOIN services s ON s.id=t.service_id WHERE t.id=? AND t.customer_user_id=?');$q->execute([$id,$_SESSION['user_id']]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Ticket not found');}$p=db()->prepare("SELECT COUNT(*) FROM queue_tickets WHERE business_id=? AND ticket_date=? AND daily_number<? AND status IN ('WAITING','CALLED')");$p->execute([$t['business_id'],$t['ticket_date'],$t['daily_number']]);$ahead=in_array($t['status'],['WAITING','CALLED'])?(int)$p->fetchColumn():0;$title='Your ticket';require 'includes/header.php';?><section class="panel narrow centered"><small>YOUR DIGITAL TICKET</small><h1><?=e($t['ticket_code'])?></h1><p><?=e($t['business_name'])?> · <?=e($t['service_name'])?></p><h2 id="status" class="status"><?=e($t['status'])?></h2><p>People ahead: <b id="ahead"><?=$ahead?></b></p><p id="updated">Updates approximately every 8 seconds.</p><a href="customer.php">Back to dashboard</a></section><script>window.ticketId=<?=$t['id']?>;</script><?php require 'includes/footer.php';?>